corrected_code:
exports.handler = async (event) => {
  const authorizedUserId = event.requestContext.authorizer?.userId;
  if (!authorizedUserId) {
    return { statusCode: 401, body: 'Unauthorized' };
  }

  // Never allow query parameters to override authenticated identity
  const s3 = new (require('@aws-sdk/client-s3').S3Client)({ region: 'us-east-1' });
  const getCmd = new (require('@aws-sdk/client-s3').GetObjectCommand)({
    Bucket: 'personal-identity-documents',
    Key: `passports/${authorizedUserId}.pdf`
  });

  const response = await s3.send(getCmd);
  const bodyContents = await response.Body.transformToString('base64');

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/pdf' },
    isBase64Encoded: true,
    body: bodyContents
  };
};
